<?php $fmt=static fn($v):string=>'৳'.number_format((float)$v,2); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/assets/css/app.css"><style>body{background:#f5f7fb}.page{max-width:1200px;margin:auto;padding:28px 18px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:18px;padding:20px;box-shadow:0 8px 30px rgba(15,23,42,.06)}.filters{display:grid;grid-template-columns:1fr 1fr 1fr 2fr auto;gap:10px}.filters input,.filters select{padding:11px;border:1px solid #dbe1ea;border-radius:10px;width:100%}.btn{display:inline-block;border:0;border-radius:10px;padding:11px 16px;background:#2563eb;color:#fff;text-decoration:none;font-weight:700}.secondary{background:#eef2f7;color:#0f172a}.summary{display:flex;justify-content:space-between;align-items:center;margin:18px 0}.total{font-size:28px;font-weight:800}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px 10px;border-bottom:1px solid #edf0f4;white-space:nowrap}.method{font-size:12px;background:#f1f5f9;padding:5px 8px;border-radius:999px}.muted{color:#64748b}@media(max-width:850px){.filters{grid-template-columns:1fr 1fr}.filters .wide{grid-column:1/-1}.top,.summary{align-items:flex-start;flex-direction:column;gap:8px}}</style><title>Collection Report · ISPLUKA</title></head><body><main class="page"><div class="top"><div><h1>Collection Report</h1><p class="muted">Completed customer collections by date and payment method.</p></div><a class="btn secondary" href="/">Dashboard</a></div><section class="card"><form class="filters"><input type="date" name="from" value="<?=htmlspecialchars($from)?>"><input type="date" name="to" value="<?=htmlspecialchars($to)?>"><select name="method"><option value="">All methods</option><?php foreach(['cash','bkash','nagad','bank','card','other'] as $m): ?><option value="<?=$m?>" <?=$method===$m?'selected':''?>><?=ucfirst($m)?></option><?php endforeach; ?></select><input class="wide" name="search" value="<?=htmlspecialchars($search)?>" placeholder="Customer, phone, code or reference"><button class="btn" type="submit">Filter</button></form><div class="summary"><div><div class="muted">Showing <?=count($rows)?> collections</div><div class="total"><?=$fmt($total)?></div></div><a class="btn secondary" href="/collection">New Collection</a></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Customer</th><th>Invoice</th><th>Reference</th><th>Method</th><th>Amount</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=htmlspecialchars((string)$r['paid_at'])?></td><td><strong><?=htmlspecialchars((string)$r['customer_name'])?></strong><br><small><?=htmlspecialchars((string)$r['customer_code'])?></small></td><td><?=htmlspecialchars((string)($r['invoice_number']??'—'))?></td><td><?=htmlspecialchars((string)$r['reference'])?></td><td><span class="method"><?=htmlspecialchars((string)$r['method'])?></span></td><td><strong><?=$fmt($r['amount'])?></strong></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="muted">No completed collection found for this filter.</td></tr><?php endif; ?></tbody></table></div></section></main></body></html>